from __future__ import annotations

import atexit
import glob
import importlib.util
import os
import sys
import sysconfig
from pathlib import Path

import setuptools
from setuptools import Extension, setup
from setuptools.command.build_ext import build_ext

HERE = Path(__file__).resolve().parent
DISTRIBUTION = "scikit-plots-skinny"
PACKAGE = "scikitplot"
#: SPDX licence expression covering every file this distribution ships.
LICENSE = "BSD-3-Clause"
#: First setuptools major release that understands ``license_expression``
#: (PEP 639); see ``_license_options``.
PEP639_SETUPTOOLS_MAJOR = 77
#: First Cython release with the ``freethreading_compatible`` directive.
CYTHON_FREETHREADING = (3, 1)
#: Compiled extension modules, as declared in libs/_tools/registry.py.
EXTENSIONS = []
#: Environment variable with which the builder asks for the multithreaded
#: code of an extension: ``1`` compiles it in, ``0`` or unset leaves it out.
#: Unset means out because that is what the full distribution's Meson build
#: does, and the two builds must produce the same behaviour until both change.
